const created=[],mutated=[],removed=[];
const white={r:1,g:1,b:1},ink={r:.14,g:.14,b:.14},muted={r:.45,g:.45,b:.45};
const rgb=h=>({r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255});
const palette=['D53939','2461D9','128247','8734D0','A75610','A92975','087D8B'];
const daily=[
{en:'plastic cup',zh:'塑料杯',desc:'用于盛装饮料的塑料容器。',cx:266.5,cy:732.5},
{en:'glass',zh:'玻璃杯',desc:'用于盛装饮料的玻璃容器。',cx:932,cy:599.5},
{en:'napkin',zh:'餐巾纸',desc:'用于擦拭或垫放的纸质物品。',cx:524,cy:769.5},
{en:'fork',zh:'叉子',desc:'用于进食的餐具。',cx:716,cy:210.5,offset:[-5,-54]}];
const flowers=[
{en:'Delphinium',zh:'翠雀',cx:285,cy:385},
{en:'Orchid',zh:'兰花',cx:310,cy:650},
{en:'Carnation',zh:'康乃馨',cx:675,cy:485,offset:[5,-13]},
{en:'Alstroemeria',zh:'六出花',cx:520,cy:485,offset:[-90,-45]},
{en:'Allium',zh:'葱属',cx:750,cy:410},
{en:'Dahlia',zh:'大丽花',cx:525,cy:630},
{en:'Rose',zh:'玫瑰',cx:735,cy:540}];
async function fontsFor(root){const fs=new Map();for(const t of root.findAllWithCriteria({types:['TEXT']}))for(const s of t.getStyledTextSegments(['fontName']))fs.set(JSON.stringify(s.fontName),s.fontName);fs.set('inter',{family:'Inter',style:'Semi Bold'});fs.set('cn',{family:'Noto Sans SC',style:'Regular'});fs.set('cnm',{family:'Noto Sans SC',style:'Medium'});await Promise.all([...fs.values()].map(f=>figma.loadFontAsync(f)));}
function textNode(parent,name,value,size,color,font='Noto Sans SC',style='Regular'){const t=figma.createText();t.fontName={family:font,style};t.characters=value;t.fontSize=size;t.lineHeight={unit:'PIXELS',value:size+6};t.fills=[{type:'SOLID',color}];t.name=name;parent.appendChild(t);return t;}
function absolute(parent,node,x,y){parent.appendChild(node);if(parent.layoutMode!=='NONE')node.layoutPositioning='ABSOLUTE';node.x=x;node.y=y;}
function cleanup(f){const content=f.findOne(n=>n.name==='结果内容');for(const n of [...content.children])if(n.name==='补充词汇'||n.name.startsWith('英文标签 · ')||n.name.startsWith('fork · ')){removed.push(n.id);n.remove();}const guide=content.findOne(n=>n.name==='释义引导');guide.primaryAxisSizingMode='FIXED';guide.resize(350,148);const title=guide.findOne(n=>n.type==='TEXT'&&n.name==='引导标题');title.characters='点标签，认识照片里的物品';title.resize(288,title.height);const body=guide.findOne(n=>n.type==='TEXT'&&n.name==='引导说明');body.characters='点圆点展开英文，再点标签查看释义。\n已展开的标签会保留，也可以收起。';body.resize(318,42);const hint=content.findOne(n=>n.type==='TEXT'&&n.name==='提示');hint.characters='点圆点展开英文 · 点标签查看释义';hint.resize(310,hint.height);mutated.push(f.id,content.id,guide.id,title.id,body.id,hint.id);}
function draw(f,defs,mask,sel){
const content=f.findOne(n=>n.name==='结果内容');const photo=content.children.find(n=>n.type==='RECTANGLE'&&n.fills.some(p=>p.type==='IMAGE'||p.type==='SOLID'));const links=[];
for(let i=0;i<defs.length;i++){const d=defs[i],color=rgb(palette[i]);const px=photo.x+photo.width*d.cx/1000,py=photo.y+photo.height*d.cy/1000;
if(mask&(1<<i)){
 const tag=figma.createAutoLayout('HORIZONTAL');tag.name='英文标签 · '+d.en;tag.paddingLeft=7;tag.paddingRight=7;tag.paddingTop=5;tag.paddingBottom=5;tag.cornerRadius=5;tag.fills=[{type:'SOLID',color:sel===i?color:white}];tag.strokes=[{type:'SOLID',color}];tag.strokeWeight=1;absolute(content,tag,0,0);
 textNode(tag,'英文词',d.en,12,sel===i?white:color,'Inter','Semi Bold');
 const tx=d.offset?px+d.offset[0]:px-tag.width/2;tag.x=Math.max(photo.x+1,Math.min(photo.x+photo.width-tag.width-1,tx));tag.y=d.offset?py+d.offset[1]:py-tag.height/2;
 if(d.offset){const sx=Math.max(tag.x,Math.min(px,tag.x+tag.width)),sy=tag.y+tag.height,minX=Math.min(sx,px),minY=Math.min(sy,py);const line=figma.createVector();line.name=d.en+' · 引线';line.vectorPaths=[{windingRule:'NONE',data:'M '+(sx-minX)+' '+(sy-minY)+' L '+(px-minX)+' '+(py-minY)}];line.fills=[];line.strokes=[{type:'SOLID',color}];line.strokeWeight=1.5;absolute(content,line,minX,minY);
 const pin=figma.createEllipse();pin.name=d.en+' · 指向点';pin.resize(6,6);pin.fills=[{type:'SOLID',color}];pin.strokes=[{type:'SOLID',color:white}];pin.strokeWeight=1;absolute(content,pin,px-3,py-3);}
 if(sel!==i)links.push({source:tag.id,mask,sel:i});
}else{
 const dot=figma.createFrame();dot.name='待展开圆点 · '+d.en;dot.resize(36,36);dot.fills=[];absolute(content,dot,px-18,py-18);
 const circle=figma.createEllipse();circle.name='物体中心圆点';circle.resize(14,14);circle.fills=[{type:'SOLID',color}];circle.strokes=[{type:'SOLID',color:white}];circle.strokeWeight=2;absolute(dot,circle,11,11);links.push({source:dot.id,mask:mask|(1<<i),sel});
}}
const guide=content.findOne(n=>n.name==='释义引导');
if(sel>=0){const d=defs[sel],color=rgb(palette[sel]);const title=guide.findOne(n=>n.type==='TEXT'&&n.name==='引导标题');title.characters=d.en+' · '+d.zh;title.fills=[{type:'SOLID',color}];const body=guide.findOne(n=>n.type==='TEXT'&&n.name==='引导说明');body.characters=d.desc||'点照片中的其他标签，继续查看。';body.resize(318,42);
 const collapse=figma.createAutoLayout('HORIZONTAL');collapse.name='收起标签';collapse.fills=[];collapse.paddingTop=3;collapse.paddingBottom=3;guide.appendChild(collapse);textNode(collapse,'操作文字','收起标签',12,color,'Noto Sans SC','Medium');links.push({source:collapse.id,mask:mask&~(1<<sel),sel:-1});
 const close=textNode(guide,'关闭释义 · 保留标签','×',20,muted,'Inter','Semi Bold');close.layoutPositioning='ABSOLUTE';close.x=318;close.y=10;links.push({source:close.id,mask,sel:-1});}
return {id:f.id,mask,sel,links};
}
async function connect(states){const map=new Map(states.map(s=>[s.mask+':'+s.sel,s.id]));const jobs=[];for(const s of states)for(const l of s.links){const target=map.get(l.mask+':'+l.sel);if(!target)throw Error('Missing state '+l.mask+':'+l.sel);const source=await figma.getNodeByIdAsync(l.source);jobs.push(source.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:target,navigation:'NAVIGATE',transition:null,resetScrollPosition:false}]}]));}await Promise.all(jobs);return jobs.length;}
